//! #417 stage B: every transfer the SMF builds or parses, checked against the
//! octets [`golden`] derives by hand from the TS 38.413 V17.9 schema and X.691
//! ALIGNED. These replace the old-vs-new oracle tests against the hand-written
//! `nextgcore-ngap` codec, which is no longer a dependency of this crate.
//!
//! Builders: for every input in range the generated bytes are the derived
//! bytes. Parsers: the derived bytes read to the expected [`DlEndpoint`]. The
//! derivations are anchored by the independent captures elsewhere in the crate
//! (`GNB_EXPECTED_SETUP_REQUEST`, the nextgsim gNB vector, and the
//! `GOLDEN_MODIFY_REQUEST_*` tables), which [`the_derivations_agree_with_the_independent_vectors`]
//! re-derives.

use super::golden::{self, BIT_RATE_MAX};
use super::*;
use proptest::prelude::*;

const ALL_CAUSES: [SmfCause; 5] = [
    SmfCause::NasNormalRelease,
    SmfCause::TransportResourceUnavailable,
    SmfCause::TransportUnspecified,
    SmfCause::ProtocolFalselyConstructedMessage,
    SmfCause::MiscUnspecified,
];

fn ep((teid, address): (u32, [u8; 4]), qfis: &[u8]) -> DlEndpoint {
    DlEndpoint {
        teid,
        address: address.to_vec(),
        bit_len: 32,
        qfis: qfis.to_vec(),
    }
}

// ---------------------------------------------------------------------------
// Strategies, all within the ranges the schema and the SMF allow.
// ---------------------------------------------------------------------------

fn tunnel() -> impl Strategy<Value = (u32, [u8; 4])> {
    (any::<u32>(), any::<[u8; 4]>())
}

/// BitRate ::= INTEGER (0..4000000000000, ...), every octet count 1..6, and
/// past it (#1163): sent as 4000000000000.
fn bit_rate() -> impl Strategy<Value = u64> {
    prop_oneof![
        Just(0u64),
        0u64..=255,
        256u64..=65_535,
        0u64..=BIT_RATE_MAX,
        Just(BIT_RATE_MAX),
        Just(BIT_RATE_MAX + 1),
        BIT_RATE_MAX + 1..,
        Just(u64::MAX)
    ]
}

fn qos_monitoring() -> impl Strategy<Value = Option<QosMonitoringRequest>> {
    prop_oneof![
        Just(None),
        Just(Some(QosMonitoringRequest::Ul)),
        Just(Some(QosMonitoringRequest::Dl)),
        Just(Some(QosMonitoringRequest::Both)),
        Just(Some(QosMonitoringRequest::Stop)),
    ]
}

fn flow() -> impl Strategy<Value = QosFlowSetup> {
    (
        0u8..=MAX_QFI,
        0u16..=255,
        (1u8..=15, any::<bool>(), any::<bool>()),
        proptest::option::of((bit_rate(), bit_rate(), bit_rate(), bit_rate())),
        proptest::option::of(0u8..=15),
        qos_monitoring(),
    )
        .prop_map(
            |(qfi, five_qi, (priority_level, cap, vuln), gbr, e_rab_id, qos_monitoring)| {
                QosFlowSetup {
                    qos_monitoring,
                    qfi,
                    five_qi,
                    arp: Arp {
                        priority_level,
                        may_trigger_pre_emption: cap,
                        pre_emptable: vuln,
                    },
                    gbr: gbr.map(|(mfbr_dl, mfbr_ul, gfbr_dl, gfbr_ul)| Gbr {
                        mfbr_dl,
                        mfbr_ul,
                        gfbr_dl,
                        gfbr_ul,
                    }),
                    e_rab_id,
                }
            },
        )
}

fn setup_request() -> impl Strategy<Value = SetupRequest> {
    (
        proptest::option::of((bit_rate(), bit_rate())),
        tunnel(),
        any::<bool>(),
        any::<bool>(),
        proptest::collection::vec(flow(), 1..=4),
    )
        .prop_map(|(ambr, ul_tunnel, dfnp, dfpa, flows)| SetupRequest {
            ambr,
            ul_tunnel,
            data_forwarding_not_possible: dfnp,
            direct_forwarding_path_availability: dfpa,
            flows,
        })
}

fn qfis(range: std::ops::RangeInclusive<usize>) -> impl Strategy<Value = Vec<u8>> {
    proptest::collection::vec(0u8..=MAX_QFI, range)
}

fn additional() -> impl Strategy<Value = Vec<((u32, [u8; 4]), Vec<u8>)>> {
    proptest::collection::vec((tunnel(), qfis(1..=2)), 0..=3)
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(256))]

    #[test]
    fn setup_request_transfer_is_the_derived_octets(r in setup_request()) {
        prop_assert_eq!(setup_request_transfer(&r).unwrap(), golden::setup_request_octets(&r));
    }

    #[test]
    fn modify_request_transfer_is_the_derived_octets(
        ambr in proptest::option::of((bit_rate(), bit_rate())),
        q in qfis(0..=4),
    ) {
        prop_assert_eq!(
            modify_request_transfer(ambr, &q).unwrap(),
            golden::modify_request_octets(ambr, &q)
        );
    }

    #[test]
    fn modify_confirm_transfer_is_the_derived_octets(
        q in qfis(1..=64),
        ul in tunnel(),
        pairs in proptest::collection::vec((tunnel(), tunnel()), 0..=3),
        failed in qfis(0..=3),
    ) {
        prop_assert_eq!(
            modify_confirm_transfer(&q, ul, &pairs, &failed).unwrap(),
            golden::modify_confirm_octets(&q, ul, &pairs, &failed)
        );
    }

    #[test]
    fn a_derived_setup_response_transfer_reads_to_its_dl_endpoint(
        dl in tunnel(),
        q in qfis(1..=4),
        more in additional(),
    ) {
        let bytes = golden::setup_response_octets(dl, &q, &more);
        prop_assert_eq!(parse_setup_response_transfer(&bytes).unwrap(), ep(dl, &q));
    }

    #[test]
    fn a_derived_modify_indication_transfer_reads_to_every_endpoint(
        dl in tunnel(),
        q in qfis(1..=4),
        more in additional(),
    ) {
        let bytes = golden::modify_indication_octets(dl, &q, &more);
        prop_assert_eq!(
            parse_modify_indication_transfer(&bytes).unwrap(),
            ModifyIndication {
                dl: ep(dl, &q),
                additional: more.iter().map(|(t, q)| ep(*t, q)).collect(),
            }
        );
    }

    #[test]
    fn a_derived_handover_request_acknowledge_transfer_reads_to_its_endpoints(
        dl in tunnel(),
        forwarding in proptest::option::of(tunnel()),
        flows in proptest::collection::vec((0u8..=MAX_QFI, any::<bool>()), 1..=4),
    ) {
        let bytes = golden::handover_request_acknowledge_octets(dl, forwarding, &flows);
        let qfis: Vec<u8> = flows.iter().map(|f| f.0).collect();
        prop_assert_eq!(
            parse_handover_request_acknowledge_transfer(&bytes).unwrap(),
            HandoverAck {
                dl: ep(dl, &qfis),
                forwarding_accepted_qfis: flows.iter().filter(|f| f.1).map(|f| f.0).collect(),
                dl_forwarding: forwarding.map(|t| ep(t, &[])),
                erab_forwarding: Vec::new(),
            }
        );
    }

    /// With and without User Plane Security Information: the hand-written
    /// decoder refused the latter (it could not skip it); the generated parse
    /// reads past it (#590).
    #[test]
    fn a_derived_path_switch_request_transfer_reads_to_its_dl_endpoint(
        dl in tunnel(),
        q in qfis(1..=64),
        security in any::<bool>(),
    ) {
        let bytes = golden::path_switch_request_octets(dl, &q, security);
        prop_assert_eq!(parse_path_switch_request_transfer(&bytes).unwrap(), ep(dl, &q));
    }

    #[test]
    fn path_switch_acknowledge_transfer_is_the_derived_octets(ul in proptest::option::of(tunnel())) {
        prop_assert_eq!(
            path_switch_request_acknowledge_transfer(ul).unwrap(),
            golden::path_switch_request_acknowledge_octets(ul)
        );
    }
}

/// The bit sink is checked against vectors that were not derived through it:
/// the nextgsim gNB's expected Setup Request, its Setup Response capture, and
/// the hand-written-out Modify Request tables in `main.rs`.
#[test]
fn the_derivations_agree_with_the_independent_vectors() {
    // main.rs GNB_EXPECTED_SETUP_REQUEST: TEID 0x00010001, 10.45.0.1, one
    // non-GBR flow QFI 1 / 5QI 9 / ARP 8, no AMBR.
    let gnb = golden::setup_request_octets(&SetupRequest {
        ambr: None,
        ul_tunnel: (0x0001_0001, [10, 45, 0, 1]),
        data_forwarding_not_possible: false,
        direct_forwarding_path_availability: false,
        flows: vec![QosFlowSetup {
            qos_monitoring: None,
            qfi: 1,
            five_qi: 9,
            arp: Arp {
                priority_level: 8,
                may_trigger_pre_emption: false,
                pre_emptable: false,
            },
            gbr: None,
            e_rab_id: None,
        }],
    });
    assert_eq!(
        gnb,
        [
            0x00, 0x00, 0x03, 0x00, 0x8b, 0x00, 0x0a, 0x01, 0xf0, 0x0a, 0x2d, 0x00, 0x01, 0x00,
            0x01, 0x00, 0x01, 0x00, 0x86, 0x00, 0x01, 0x00, 0x00, 0x88, 0x00, 0x07, 0x00, 0x01,
            0x00, 0x00, 0x09, 0x1c, 0x00,
        ]
    );
    // main.rs GNB_SETUP_RESPONSE_TRANSFER: 0x00020002 / 10.46.0.1 / QFI 1.
    assert_eq!(
        golden::setup_response_octets((0x0002_0002, [10, 46, 0, 1]), &[1], &[]),
        [0x00, 0x03, 0xe0, 0x0a, 0x2e, 0x00, 0x01, 0x00, 0x02, 0x00, 0x02, 0x00, 0x01]
    );
    // main.rs GOLDEN_MODIFY_REQUEST_AMBR_ONLY and _AMBR_PLUS_QOS_FLOW_ADD.
    assert_eq!(
        golden::modify_request_octets(Some((1_000_000_000, 250_000)), &[]),
        [
            0x00, 0x00, 0x01, 0x00, 0x82, 0x00, 0x09, 0x0c, 0x3b, 0x9a, 0xca, 0x00, 0x20, 0x03,
            0xd0, 0x90,
        ]
    );
    assert_eq!(
        golden::modify_request_octets(Some((200_000_000, 100_000_000)), &[1]),
        [
            0x00, 0x00, 0x02, 0x00, 0x82, 0x00, 0x0a, 0x0c, 0x0b, 0xeb, 0xc2, 0x00, 0x30, 0x05,
            0xf5, 0xe1, 0x00, 0x00, 0x87, 0x00, 0x03, 0x00, 0x00, 0x80,
        ]
    );
}

/// The cause transfers, as the octets [`golden::cause_transfer_octets`]'s doc
/// works out, so the table is pinned twice.
#[test]
fn cause_transfers_are_the_derived_octets() {
    let expected: [&[u8]; 5] = [&[0x10], &[0x08], &[0x0a], &[0x1a, 0x80], &[0x22, 0x80]];
    for (cause, octets) in ALL_CAUSES.into_iter().zip(expected) {
        assert_eq!(golden::cause_transfer_octets(cause), octets, "{cause:?}");
        assert_eq!(
            modify_indication_unsuccessful_transfer(cause).unwrap(),
            octets,
            "{cause:?}"
        );
        assert_eq!(
            release_command_transfer_with(cause).unwrap(),
            octets,
            "{cause:?}"
        );
    }
    assert_eq!(release_command_transfer().unwrap(), [0x10]);
}

/// The no-change form is one octet: all presence bits zero.
#[test]
fn an_empty_path_switch_acknowledge_is_one_zero_octet() {
    assert_eq!(
        path_switch_request_acknowledge_transfer(None).unwrap(),
        [0x00]
    );
}

/// TS 38.413 §9.3.4.9 / the Rel-17 ASN.1:
///
/// ```text
/// PathSwitchRequestAcknowledgeTransfer ::= SEQUENCE {
///     uL-NGU-UP-TNLInformation  UPTransportLayerInformation  OPTIONAL,
///     securityIndication        SecurityIndication           OPTIONAL,
///     iE-Extensions  ProtocolExtensionContainer { {...} }    OPTIONAL,
///     ...
/// }
/// ```
///
/// Three presence bits after the extension bit. The hand-written encoder this
/// crate used before #590 wrote five -- two for `newSecurityResult` and
/// `qosFlowToReleaseList`, which this SEQUENCE does not have.
///
/// Both vectors are derived by hand (X.691 ALIGNED), for UL tunnel
/// 10.45.0.1 / TEID 0x00010001:
///
/// ```text
/// schema:       0 1 0 0          ext, uL-NGU-UP-TNLInformation, securityIndication, iE-Ext
///               0                UPTransportLayerInformation CHOICE index 0 (gTPTunnel)
///               0 0              GTPTunnel ext, iE-Extensions
///               0                TransportLayerAddress SIZE ext
///               0001 1111        length 32 - 1, 8-bit field (range 160)
///               0a 2d 00 01      the address, octet-aligned (bit 16 already is)
///               00 01 00 01      GTP-TEID, SIZE(4) fixed
///            =  40 1f 0a 2d 00 01 00 01 00 01
///
/// pre-#590:     0 1 0 0 0 0      two spurious presence bits
///               0 0 0 0 0001 1111 + 6 padding bits, then the same 8 octets
///            =  40 07 c0 0a 2d 00 01 00 01 00 01
/// ```
///
/// A conformant decoder reads the pre-#590 bytes as an 8-bit address (length
/// field 0x07) of 0xc0 and TEID 0x0a2d0001.
#[test]
fn path_switch_acknowledge_follows_the_schema_not_the_pre_590_layout() {
    let ul = (0x0001_0001, [10, 45, 0, 1]);
    let new = path_switch_request_acknowledge_transfer(Some(ul)).unwrap();
    let old = [
        0x40, 0x07, 0xc0, 0x0a, 0x2d, 0x00, 0x01, 0x00, 0x01, 0x00, 0x01,
    ];
    assert_eq!(
        new,
        [0x40, 0x1f, 0x0a, 0x2d, 0x00, 0x01, 0x00, 0x01, 0x00, 0x01]
    );

    // The generated decoder -- what a conformant gNB runs -- reads the tunnel
    // from the new bytes, and a different one from the old.
    let read = |bytes: &[u8]| {
        nextgcore_ngap_gen::decode_contained::<g::PathSwitchRequestAcknowledgeTransfer>(bytes)
            .unwrap()
            .ul_ngu_up_tnl_information
            .map(|t| endpoint("test", t, Vec::new()).unwrap())
    };
    assert_eq!(read(&new), Some(ep(ul, &[])));
    assert_eq!(
        read(&old),
        Some(DlEndpoint {
            teid: 0x0a2d_0001,
            address: vec![0xc0],
            bit_len: 8,
            qfis: Vec::new(),
        })
    );
}

/// What the hand-written encoder refused, the generated builders refuse too.
#[test]
fn out_of_range_values_are_refused() {
    let base = SetupRequest {
        ambr: None,
        ul_tunnel: (1, [10, 0, 0, 1]),
        data_forwarding_not_possible: false,
        direct_forwarding_path_availability: false,
        flows: vec![QosFlowSetup {
            qos_monitoring: None,
            qfi: 1,
            five_qi: 9,
            arp: Arp {
                priority_level: 8,
                may_trigger_pre_emption: false,
                pre_emptable: false,
            },
            gbr: None,
            e_rab_id: None,
        }],
    };
    let with = |f: &dyn Fn(&mut QosFlowSetup)| {
        let mut r = base.clone();
        f(&mut r.flows[0]);
        r
    };
    for (name, r) in [
        ("QFI 64", with(&|f| f.qfi = 64)),
        ("ARP 0", with(&|f| f.arp.priority_level = 0)),
        ("ARP 16", with(&|f| f.arp.priority_level = 16)),
        ("5QI 256", with(&|f| f.five_qi = 256)),
        (
            "no flows",
            SetupRequest {
                flows: Vec::new(),
                ..base.clone()
            },
        ),
    ] {
        assert!(setup_request_transfer(&r).is_err(), "{name}");
    }
    assert!(modify_request_transfer(None, &[64]).is_err());
    assert!(modify_confirm_transfer(&[], (1, [10, 0, 0, 1]), &[], &[]).is_err());
    assert!(modify_confirm_transfer(&[64], (1, [10, 0, 0, 1]), &[], &[]).is_err());
}

/// A Setup Response Transfer whose iE-Extensions carry one entry with an id the
/// schema does not define (9), at each criticality: refused at `reject`,
/// skipped otherwise (TS 38.413 §10.3.4.1).
///
/// The derived bytes: [`golden::setup_response_octets`] for 10.45.0.3 / TEID 7
/// / QFI 9 with its iE-Extensions presence bit (bit 4 of octet 0, `0x08`) set,
/// then the container octet-aligned at the end: count-1 `00 00`, id `00 09`,
/// criticality in the top two bits of the next octet, open type length `01`
/// and a one-octet value `00`.
#[test]
fn an_unknown_extension_is_skipped_unless_its_criticality_is_reject() {
    let dl = (0x0000_0007, [10, 45, 0, 3]);
    let expected = ep(dl, &[9]);
    let base = golden::setup_response_octets(dl, &[9], &[]);
    assert_eq!(parse_setup_response_transfer(&base).unwrap(), expected);
    for (criticality, accepted) in [(0u8, false), (1, true), (2, true)] {
        let mut bytes = base.clone();
        bytes[0] |= 0x08;
        bytes.extend_from_slice(&[0x00, 0x00, 0x00, 0x09, criticality << 6, 0x01, 0x00]);
        assert_eq!(
            parse_setup_response_transfer(&bytes).ok(),
            accepted.then(|| expected.clone()),
            "criticality {criticality}"
        );
    }
}
